 20	/**
 21	 * 주문 명령 컨트롤러 (Kafka 비동기 처리)
 22	 */
 23	@RestController
 24	@RequestMapping("/orders")
 25	@RequiredArgsConstructor
 26	@Slf4j
 27	@Validated
 28	public class OrderCommandController {
 29	
 30	    private final OrderEventProducer orderEventProducer; // 기존 OrderCommandService 대신 Kafka Producer 사용
 31	
 32	    /**
 33	     * 주문의 결제 및 배송 정보를 처리합니다.
 34	     * ⭐ 전체 처리를 Kafka로 비동기 처리하고 즉시 응답
 35	     *
 36	     * @param orderId 주문 ID
 37	     * @param requestDto 결제 및 배송 요청 정보
 38	     * @return 처리 진행 상태 응답
 39	     * @throws OrderAccessDeniedException 주문에 대한 접근 권한이 없는 경우
 40	     * @throws InvalidPaymentShipmentDataException 결제 및 배송 정보가 유효하지 않은 경우
 41	     */
 42	    @PostMapping("/{orderId}/process-payment-shipment")
 43	    public ResponseEntity<ResponseDto<Map<String, Object>>> processPaymentAndShipment(
 44	            @PathVariable("orderId") Long orderId,
 45	            @RequestBody @Valid PayAndShipmentRequestDto requestDto
 46	    ) {
 47	        // 사용자 이메일 추출 및 검증
 48	        String email = SecurityUtils.extractAndValidateEmailForOrder("결제 및 배송 처리");
 49	
 50	        log.info("사용자 [{}]가 주문(ID: {})의 결제 및 배송 처리를 요청합니다.", email, orderId);
 51	
 52	        try {
 53	            // Kafka로 비동기 주문 처리 이벤트 발행
 54	            orderEventProducer.sendOrderProcessingEvent(orderId, email, requestDto);
 55	
 56	            // 즉시 응답 데이터 생성
 57	            Map<String, Object> responseData = new HashMap<>();
 58	            responseData.put("orderId", orderId);
 59	            responseData.put("status", "PROCESSING");
 60	            responseData.put("message", "주문이 접수되었습니다. 결제를 처리하고 있습니다.");
 61	            responseData.put("estimatedProcessingTime", "1-3분");
 62	            responseData.put("websocketTopic", "/topic/order/" + orderId);
 63	            responseData.put("statusCheckUrl", "/api/orders/" + orderId + "/status");
 64	
 65	            log.info("주문 처리 이벤트 발행 완료: 주문ID={}, 사용자={}", orderId, email);
 66	
 67	            // 202 Accepted 응답 (처리 중임을 명시)
 68	            return ResponseEntity.status(HttpStatus.ACCEPTED)
 69	                    .body(ResponseDto.success(responseData, "주문 처리가 시작되었습니다. 처리 완료 시 알림을 받으실 수 있습니다."));
 70	
 71	        } catch (Exception e) {
 72	            log.error("주문 처리 이벤트 발행 실패: 주문ID={}, 사용자={}, 오류={}", orderId, email, e.getMessage(), e);
 73	
 74	            // 실패 시 즉시 오류 응답
 75	            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
 76	                    .body(ResponseDto.error("ORDER_PROCESSING_FAILED",
 77	                            "주문 처리 요청 중 오류가 발생했습니다: " + e.getMessage()));
 78	        }
 79	    }
 80	
 81	    //    /**
 82	//     * 주문의 결제 및 배송 정보를 처리합니다.
