   524	                    payment != null ? payment.getId() : "null",
   525	                    e.getErrorCode().getCode(), e.getMessage());
   526	            throw e; // 이미 PaymentException이면 그대로 전파
   527	        } catch (Exception e) {
   528	            log.error("결제 상태 변경 중 예상치 못한 오류 발생: 결제ID={}, 오류={}",
   529	                    payment != null ? payment.getId() : "null", e.getMessage(), e);
   530	            throw new PaymentException(PaymentErrorCode.PAYMENT_UPDATE_FAILED,
   531	                    "결제 상태 변경 중 오류가 발생했습니다.", e);
   532	        }
